49	// clusterEvents keeps what touches the cluster, in order: the preflights and
50	// the library calls. The constructors (newRunner, newStore, ...) are left out.
51	func (h *harness) clusterEvents() []string {
52		var out []string
53		for _, e := range h.eventList() {
54			switch {
55			case strings.HasPrefix(e, "preflight:"), e == "deploy", e == "ensureUpstream", e == "provision", e == "seed", e == "destroy":
56				out = append(out, e)
57			}
58		}
59		return out
60	}
