124			t.Errorf("Seed params = %+v", h.seedParams)
125		}
126		if !h.descriptorSeenAtSeed {
127			t.Error("the descriptor of the previous run should still be there while Seed runs")
128		}
129	
130		// The descriptor: the previous provisioning, the hosts of the preflight, the
131		// data set Seed returned.
132		p := nexusbench.Defaults()
