137			t.Fatalf("no descriptor: %v", err)
138		}
139		want := wantDescriptorBytesWith(t, p, nexusbench.DeployResult{NodeIP: h.preflightRes.NodeIP}, previousProvisioning, h.seedRes)
140		if !bytes.Equal(got, want) {
