180			notCalled []string
181		}{
182			{"seed fails", func(h *harness) {
183				h.seedErr = be
184				// Seed returns what it had put in place together with the error.
185				h.seedRes = nexusbench.SeedResult{Images: nexusbench.Dataset()[:2]}
186			}, be.Error(), nil},
187			{"seed fails with an error that is not a BenchError", func(h *harness) {
188				h.seedErr = errors.New("skopeo said: " + secretMarker)
189			}, "skopeo said: " + secretMarker, nil},
190			{"preflight fails", func(h *harness) { h.preflightErr = be }, be.Error(), []string{"seed"}},
191			{"skopeo is missing", func(h *harness) { h.newCopierErr = skopeoMissing }, skopeoMissing.Error(), []string{"preflight:OpSeed", "seed"}},
192			{"kubectl is missing", func(h *harness) {
193				h.newRunnerErr = &nexusbench.BenchError{Kind: nexusbench.KubectlMissing, Cause: "kubectl was not found on PATH", Check: "run `mise install`"}
194			}, "", []string{"preflight:OpSeed", "seed"}},
195			{"the forwarder cannot be built", func(h *harness) { h.newForwarderErr = be }, be.Error(), []string{"preflight:OpSeed", "seed"}},
196			{"the secrets path is refused", func(h *harness) {
197				h.newStoreErr = &nexusbench.BenchError{Cause: "the secrets path is in a repository and not ignored", Check: "set NEXUS_BENCH_SECRETS"}
198			}, "", []string{"preflight:OpSeed", "seed"}},
199		}
200		for _, tt := range tests {
201			t.Run(tt.name, func(t *testing.T) {
202				h := newHarness(t)
203				tt.setup(h)
204				before := h.writePreviousDescriptor()
205				code, stdout, stderr := h.run("seed")
206				if code != 1 {
207					t.Errorf("exit code = %d, want 1", code)
208				}
209				want := tt.wantText
210				var asBench *nexusbench.BenchError
211				if want == "" && errors.As(firstError(h), &asBench) {
212					want = asBench.Error()
213				}
214				if got := strings.TrimSpace(stderr); got != want {
215					t.Errorf("stderr = %q, want exactly %q", got, want)
216				}
217				requireClean(t, stdout, stderr)
218				for _, e := range tt.notCalled {
219					if h.has(e) {
220						t.Errorf("%s must not run after this failure, events: %v", e, h.eventList())
221					}
222				}
223				after, err := os.ReadFile(h.descriptor)
224				if err != nil || !bytes.Equal(before, after) {
225					t.Errorf("the descriptor of the previous run was changed (err=%v)", err)
226				}
227			})
228		}
