466	func TestUpDeploysEnsuresTheUpstreamProvisionsThenSeeds(t *testing.T) {
467		h := newHarness(t)
468		h.deployRes = nexusbench.DeployResult{ReachableHosts: []string{"127.0.0.1", "192.168.1.31"}, NodeIP: "192.168.1.31"}
469		code, stdout, stderr := h.run("up", "--accept-eula")
470		if code != 0 {
471			t.Fatalf("exit code = %d\nstdout: %s\nstderr: %s", code, stdout, stderr)
472		}
473	
474		// The exact order of the calls that reach the cluster. Deploy runs its own
475		// preflight(OpUp), so one of the command before it is allowed, for OpUp only.
476		got := h.clusterEvents()
477		if len(got) > 0 && got[0] == "preflight:OpUp" {
478			got = got[1:]
479		}
480		if want := []string{"deploy", "ensureUpstream", "provision", "seed"}; !slices.Equal(got, want) {
481			t.Fatalf("cluster calls = %v, want %v (all: %v)", got, want, h.eventList())
482		}
483		for _, op := range h.preflightOps {
484			if op != nexusbench.OpUp {
485				t.Errorf("up ran a preflight for %s, want OpUp only", opName(op))
486			}
487		}
488		// Everything that can refuse comes before the first write to the cluster.
489		for _, e := range []string{"newRunner", "newStore", "newForwarder", "newCopier"} {
490			if !h.before(e, "deploy") {
491				t.Errorf("%s must happen before Deploy, events: %v", e, h.eventList())
492			}
493		}
494		for _, e := range []string{"destroy", "readUpstream", "readImages:docker-hosted", "readImages:docker-proxy"} {
495			if h.has(e) {
496				t.Errorf("up called %s: %v", e, h.eventList())
497			}
498		}
499	
500		// What each step was given.
501		if h.ensureRunner != nexusbench.Runner(h.runner) || h.ensureClock != nexusbench.Clock(h.clock) {
502			t.Error("EnsureUpstream was not given the runner and the clock of the deps")
503		}
504		d := h.seedDeps
505		if d.Runner != nexusbench.Runner(h.runner) || d.Forwarder != nexusbench.PortForwarder(h.forward) ||
506			d.Copier != nexusbench.ImageCopier(h.copier) || d.Clock != nexusbench.Clock(h.clock) || d.Store != nexusbench.SecretStore(h.store) {
507			t.Errorf("SeedDeps = %+v, want the runner, forwarder, copier, clock and store of the deps", d)
508		}
509		if h.seedURL != "http://127.0.0.1:30481" || h.seedURL != h.provisionURL {
510			t.Errorf("Seed base URL = %q, Provision base URL = %q, want the same loopback origin", h.seedURL, h.provisionURL)
511		}
512		if !reflect.DeepEqual(h.seedParams, h.provisionParams) || !reflect.DeepEqual(h.ensureParams, h.provisionParams) {
513			t.Errorf("the steps were not given the same parameters:\nprovision %+v\nensure    %+v\nseed      %+v", h.provisionParams, h.ensureParams, h.seedParams)
514		}
515		if h.descriptorSeenAtSeed || h.descriptorSeenAtProvision {
516			t.Error("the descriptor existed before the seed finished")
517		}
518	
519		// The descriptor describes the whole data set, the proxy created and a
520		// member of the group.
521		got2, err := os.ReadFile(h.descriptor)
522		if err != nil {
523			t.Fatalf("no descriptor written: %v", err)
524		}
525		want := wantDescriptorBytes(t, nexusbench.Defaults(), h.deployRes, h.provisionRes)
526		if !bytes.Equal(got2, want) {
527			t.Errorf("descriptor bytes differ from BuildDescriptor(..., SeedResult{Dataset()}):\n got %s\nwant %s", got2, want)
528		}
529		desc, err := nexusbench.LoadDescriptor(h.descriptor)
530		if err != nil {
531			t.Fatal(err)
532		}
533		if len(desc.Dataset) != len(nexusbench.Dataset()) {
534			t.Errorf("the descriptor lists %d images, want %d", len(desc.Dataset), len(nexusbench.Dataset()))
535		}
536		var proxy, group bool
537		for _, r := range desc.Repositories {
538			proxy = proxy || r.Name == "docker-proxy"
539			group = group || (r.Type == "group" && slices.Contains(r.Members, "docker-proxy") && slices.Contains(r.Members, "docker-hosted"))
540		}
541		if !proxy || !group {
542			t.Errorf("the descriptor lacks the proxy (%v) or its place in the group (%v)", proxy, group)
543		}
544	
545		// Output: the progress of every step, in the order they ran.
546		last := -1
547		for _, marker := range []string{progressMarker + " deploy", progressMarker + " ensureUpstream", progressMarker + " provision", "seed: " + progressMarker, h.descriptor} {
548			i := strings.Index(stdout, marker)
549			if i < 0 {
550				t.Errorf("stdout lacks %q:\n%s", marker, stdout)
551				continue
552			}
553			if i < last {
554				t.Errorf("stdout shows %q out of order:\n%s", marker, stdout)
555			}
556			last = i
557		}
558		if stderr != "" {
559			t.Errorf("stderr = %q, want empty for a default bench", stderr)
560		}
561		requireClean(t, stdout, stderr)
562	}
