883			// wantRead: whether the listings are read at all.
884			wantRead bool
885		}{
886			{"the listing fails", func(h *harness) { h.readImagesErr = benchError() }, nil, true},
887			{"Nexus does not answer", func(h *harness) { h.prober.err = errors.New("refused " + secretMarker) }, nil, false},
888			{"anonymous access is off", func(*harness) {}, []string{"--anonymous=false"}, false},
889			{"no descriptor to compare with", func(h *harness) { _ = os.Remove(h.descriptor) }, nil, false},
890			{"the descriptor lists no image", func(h *harness) {
891				writeDescriptorAt(h.t, h.descriptor, nexusbench.Defaults(), h.deployRes, h.provisionRes, nexusbench.SeedResult{})
892			}, nil, false},
893		}
894		for _, tt := range tests {
895			t.Run(tt.name, func(t *testing.T) {
896				h := newHarness(t)
897				h.writeDescriptor(nexusbench.Defaults(), h.deployRes, h.provisionRes)
898				tt.setup(h)
899				code, stdout, stderr := h.run(append([]string{"status"}, tt.args...)...)
900				if code != 0 {
901					t.Fatalf("exit code = %d (unknown is a finding, not a failure)\nstdout: %s\nstderr: %s", code, stdout, stderr)
902				}
903				if got := statusLines(stdout)["dataset"]; !strings.HasPrefix(got, "unknown") {
904					t.Errorf("dataset line = %q, want it to start with \"unknown\":\n%s", got, stdout)
905				}
906				if !tt.wantRead && (h.has("readImages:docker-hosted") || h.has("readImages:docker-proxy")) {
907					t.Errorf("status read the listings although it cannot compare them: %v", h.eventList())
908				}
909				requireClean(t, stdout, stderr)
910				requireStatusReadsOnly(t, h)
911			})
912		}
913	}
914	
915	// status reads: no skopeo, no port-forward, no seed, no stored secret, and REST
916	// only on the loopback origin, only the two repositories that hold the data set.
917	func requireStatusReadsOnly(t *testing.T, h *harness) {
918		t.Helper()
919		for _, e := range h.eventList() {
920			switch e {
921			case "seed", "newCopier", "newForwarder", "newStore", "newInitial", "deploy", "provision", "ensureUpstream", "destroy":
922				t.Errorf("status called %s, which is not a read: %v", e, h.eventList())
923			}
924			if repo, ok := strings.CutPrefix(e, "readImages:"); ok && repo != "docker-hosted" && repo != "docker-proxy" {
925				t.Errorf("status listed %s: only docker-hosted and docker-proxy hold the data set, and the group must never be read (F9)", repo)
926			}
927		}
928		for _, u := range h.readImagesURLs {
929			if u != "http://127.0.0.1:30481" {
930				t.Errorf("status listed images at %q, want the loopback REST origin", u)
931			}
932		}
933	}
