// the data set is fixed in the code, and provision touches neither the images nor
// the upstream. For another bench, or none, the data set is empty, and when that
// drops a data set the command says so. A descriptor that cannot be read (none,
// or schema 1) has nothing to keep.
func (s *session) keptDataset() nexusbench.SeedResult {
	prev, err := nexusbench.LoadDescriptor(s.descriptorPath())
	if err != nil || len(prev.Dataset) == 0 {
		return nexusbench.SeedResult{}
	}
