			if err == nil {
				t.Fatal("Seed accepted a repository that holds more than the data set")
			}
			_ = requireKind(t, err, SeedFailed)
			msg := err.Error()
			for _, r := range msg {
				if (unicode.IsControl(r) && r != '\n') || r == 0x7f {
					t.Fatalf("the message carries the control character %U:\n%q", r, msg)
				}
